-- Resources content for Sourcework research, Phase A (CLAUDE.md, "Resources stay in step with
-- the code"). Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-research',
  p_tool_key => 'transcription',
  p_title => 'Research questions and data points',
  p_summary => 'Set a project''s questions, extract data points from each source, and review them beside the transcript.',
  p_screen_keys => array['sourcework.setup', 'sourcework.source'],
  p_sort_order => 19,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Research questions, background notes and data points help you find what each source says about what you are trying to learn. Everything the model suggests waits for your decision, and nothing is quoted or used until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Set up the project"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select "},{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":", at the right of the tabs. "},{"type":"text","text":"Where this project stands","marks":[{"type":"bold"}]},{"type":"text","text":" is a status, not a sequence: new sources can arrive at any time and send the project back to extraction."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add the questions you are trying to answer. The ⋮ beside a question moves it up or down, or archives it. Archived questions keep their data points and can be restored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Background notes are web pages the model found that explain the places, events and terms your sources mention. They are gathered when you add or change questions and before sources are extracted. Dismiss one that is wrong, or choose Refresh to look again. Notes are background only: they are never quoted and never count as evidence."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Extract data points"}]},{"type":"paragraph","content":[{"type":"text","text":"On the Sources tab, choose "},{"type":"text","text":"Extract data points","marks":[{"type":"bold"}]},{"type":"text","text":". Each source is read on its own and up to three at a time. You can leave the page while it runs, as long as the browser tab stays open. A source that is still transcribing can be extracted once it finishes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review them in the source"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a source from its project and switch the panel beside the transcript from "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" to "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":". Each data point is a short paraphrase with the passages it rests on, underlined in lime. A dashed card and dashed underline are suggestions you have not reviewed yet."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept keeps it. Reject hides it, and the Rejected filter brings it back."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit rewords the claim and accepts it. The model's own wording is kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Play listens to the passage, so you can check the paraphrase against what was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extract again later: accepted and rejected data points are kept, and only suggestions you have not reviewed are replaced."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A data point is a paraphrase. To use the speaker's own words, make an excerpt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview audio and text are sent to an outside service to be read, as they are for transcription."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the Excerpts tab holds the switch, and the player stays docked at the bottom."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-research-prompts',
  p_tool_key => 'transcription',
  p_title => 'Maintaining the research prompts',
  p_summary => 'For editors: edit the wording, try a draft against the live version, publish and roll back.',
  p_screen_keys => array['sourcework.editors'],
  p_sort_order => 20,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors maintain the wording the research steps use. You need the Editor role on Sourcework, which an administrator grants on the user's access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a prompt"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Research prompts","marks":[{"type":"bold"}]},{"type":"text","text":" from the Projects page. Choose Background or Extraction guide, edit the text and it saves itself as a draft only you can see. The wording decides what counts as a data point and how a claim reads; the shape of the answer is fixed by the code, and "},{"type":"text","text":"What the model is given and returns","marks":[{"type":"bold"}]},{"type":"text","text":" shows both."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try a draft"}]},{"type":"paragraph","content":[{"type":"text","text":"For the extraction guide, "},{"type":"text","text":"Try this draft","marks":[{"type":"bold"}]},{"type":"text","text":" runs the live version and your draft on the same source and shows what changed: what both found, and what only one did. Nothing is added to any project, and results are kept for 14 days and are visible only to you."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish… asks for a one-line note about what changed, then makes the draft the live version for every project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists earlier versions with the share of data points people accepted. Make live again moves an earlier version back into use. Nothing is deleted."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-12-sourcework-research',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-12',
  p_title => 'Sourcework: research questions and data points',
  p_guide_slugs => array['sourcework-research', 'sourcework-research-prompts'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework projects can now hold research questions and web background notes on a new Setup tab. Sources can be extracted into data points, short paraphrases with the passages they rest on, which you accept, edit or reject beside the transcript or PDF. Editors can tune the wording the model uses, try a draft against the live version, and publish or roll back."}]}]}$body$
);
